 @Bean CommandLineRunner refreshDebtorDossiers(DebtorDossierRepository dossiers){return args->{
  dossiers.findBySlug("trx-o-parque").ifPresent(d->{d.refresh("Sociedade Beneficente de Senhoras – Hospital Sírio-Libanês (Locatária/devedora dos créditos); Bari Securitizadora S.A. como emissora","61.590.410/0001-24 (Locatária) — emissora Bari Securitizadora, CNPJ 10.608.405/0001-60","Hospital Sírio-Libanês (entidade beneficente sem fins lucrativos); cedente é o TRX Real Estate FII, CNPJ 28.548.288/0001-52, administrado pela BRL Trust","Saúde (locação atípica hospitalar)","Associação/entidade beneficente de direito privado — não é SPE","CRI da 74ª emissão, série única, R$ 173.309.244,79, emitido em 29/05/2026 com vencimento em 09/05/2046 e remuneração de 100% CDI + 1,0% a.a. ISIN BRASTECRI5A6. Agente fiduciário: Oliveira Trust; custodiante e investidor original: BR Partners. Divergência a checar: o relatório do KNCR rotula a posição como \"TRX — O Parque\", mas o termo é do CRI Sírio-Libanês (TRX Multiativos).","O lastro são 80% de cada parcela do aluguel (parcela não variável e variável) do Contrato de Locação Atípica celebrado em 19/12/2023, aditado em 23/05/2024 e 24/11/2025. Não há demonstrações financeiras da Locatária vinculadas nesta base.","Alienação fiduciária dos imóveis locados (matrículas 290.388 a 290.405 do 15º RI de São Paulo); alienação fiduciária do Imóvel Piraporinha (matrícula 65.047, Diadema/SP); cessão fiduciária dos recebíveis; Fundo de Reserva e Fundo de Despesas. Atenção: sobre os mesmos imóveis já existe alienação fiduciária anterior em favor da Opea (registro nº 03 das matrículas), constituída em 17/08/2023.","Sem evento de inadimplemento registrado. Houve assembleia de titulares em 09/06/2026 e dois aditamentos ao termo (29/05/2026 e 09/06/2026), ligados à oferta secundária.","Fonte primária: Termo de Securitização assinado da 74ª emissão da Bari Securitizadora, obtido no portal público da BariSec.","https://barisec.com.br/emissoes/26E4046156");dossiers.save(d);});
  dossiers.findBySlug("edificio-o-parque").ifPresent(d->{d.refresh("OPQ Fundo de Investimento Imobiliário – FII (devedor); Opea Securitizadora S.A. como emissora","49.152.919/0001-90 (devedor) — emissora Opea Securitizadora, CNPJ 02.773.542/0001-22","Fundo de investimento imobiliário sem controlador identificado no termo","Escritórios","Fundo de investimento imobiliário — não é SPE nem companhia operacional","CRI da 119ª emissão, série única, R$ 215.904.000, emitido em 10/08/2023 com vencimento em 24/03/2028, CDI + 2,5% a.a., amortização bullet, juros mensais. ISIN BRRBRACRIH88. Classificação Anbima: corporativo, concentrado, imóvel comercial, compra e venda a prazo. A Vórtx classifica o risco como pulverizado.","O lastro é a compra e venda a prazo de unidades autônomas e vagas do empreendimento O Parque, fração ideal da matrícula 266.552 do 15º RI de São Paulo. Não há demonstrações financeiras do devedor vinculadas nesta base.","Alienação fiduciária do imóvel, cessão fiduciária de direitos creditórios, alienação fiduciária de cotas, carta fiança ou Fundo de Reserva, e ESA.","Classificada como adimplente pelo agente fiduciário, mas com 12 obrigações vencidas em aberto entre 01/04/2024 e 10/08/2026: 6 de demonstrações financeiras, 3 de relatórios periódicos, 2 de razão de garantia e 1 de formalização de documentos. A maior parte recai sobre deveres de informação da emissora, não sobre pagamento.","Fontes primárias: Termo de Securitização da 119ª emissão e contrato de cessão de crédito, mais o resumo e as notificações do agente fiduciário Vórtx.","https://www.vortx.com.br/investidor/dcm/operacao?id=90496");dossiers.save(d);});
  dossiers.findBySlug("cpof-fl-plaza").ifPresent(d->{d.refresh("A confirmar no termo de securitização — emissora Riza Securitizadora S.A. (antiga Virgo)","A confirmar no termo de securitização","A confirmar no termo de securitização; o agente fiduciário identifica a operação internamente como caso Capitania","Escritórios","A confirmar no termo de securitização","CRI da 250ª emissão, 2ª série, R$ 150.000.000 (150.000 CRI de R$ 1.000), emitido em 24/02/2025 com vencimento em 22/09/2034, CDI + 2,0% a.a., juros mensais. ISIN BRIMWLCRIMC4. Risco classificado como corporativo. Distribuição sob a Res. CVM 160.","Não há demonstrações financeiras da devedora vinculadas nesta base; o termo não está publicado na área aberta do agente fiduciário.","Alienação fiduciária de imóvel e cessão fiduciária de direitos creditórios, conforme cadastro de garantias do agente fiduciário.","Adimplente e sem nenhuma obrigação vencida em aberto no cadastro do agente fiduciário — o melhor histórico entre as operações já verificadas.","Fonte primária: resumo público da operação no agente fiduciário Vórtx. O termo ainda não foi localizado em fonte aberta, por isso devedora, CNPJ e grupo seguem a confirmar.","https://www.vortx.com.br/investidor/dcm/operacao?id=94955");dossiers.save(d);});
  dossiers.findBySlug("jw-marriott").ifPresent(d->{d.refresh("A confirmar no termo de securitização — emissora Opea Securitizadora S.A.","A confirmar no termo de securitização (emissora Opea, CNPJ 02.773.542/0001-22)","A confirmar no termo de securitização","Hotelaria","A confirmar no termo de securitização","CRI da 455ª emissão, série única, R$ 160.000.000, emitido em 14/08/2025 com vencimento em 27/08/2035, CDI + 1,60% a.a., juros e amortização mensais. ISIN BRRBRACRIX62. Risco classificado como corporativo.","A cláusula 7.4 do termo prevê índice de cobertura apurado mensalmente desde agosto de 2025, com base em relatório gerencial mensal do devedor enviado ao agente fiduciário. Esses relatórios não são públicos e as apurações constam como pendentes.","Alienação fiduciária de imóvel e de ações, cessão fiduciária de direitos creditórios, fundo e seguro. O registro do Contrato de Cessão em cartório de títulos e documentos, obrigação do devedor com vencimento em 15/09/2025, consta como não cumprido.","Alerta. Formalmente adimplente, mas com 23 obrigações vencidas em aberto entre 15/09/2025 e 28/08/2026, das quais 12 de razão de garantia e 4 de formalização de garantia — ou seja, recaem sobre o devedor e sobre a cobertura da operação, não apenas sobre deveres de informação da emissora. A Vórtx emitiu notificações mensais de descumprimento ao longo de todo o período.","Fontes primárias: resumo da operação e notificações de descumprimento emitidas pelo agente fiduciário Vórtx. O termo não está publicado na área aberta, por isso devedora e CNPJ seguem a confirmar.","https://www.vortx.com.br/investidor/dcm/operacao?id=96057");dossiers.save(d);});
  dossiers.findBySlug("ed-eldorado").ifPresent(d->{d.refresh("Não há devedora única: o termo define como Devedor os locatários dos Contratos de Locação. Emissora: Opea Securitizadora S.A.","A confirmar — o Anexo IX, que relaciona os locatários, não consta da versão pública do termo","Risco pulverizado entre os inquilinos do Eldorado Business Tower; cedente é o EBT Fundo de Investimento Imobiliário, CNPJ 21.085.863/0001-89","Escritórios","Carteira de contratos de locação — não é SPE nem devedora corporativa única","CRI da 279ª emissão, 1ª série (o termo cobre 1ª e 2ª séries), R$ 101.450.000, emitido em 03/05/2024 com vencimento em 15/03/2033, CDI + 1,85% a.a., amortização bullet e juros mensais. ISIN BRRBRACRIO48. Agente fiduciário: Vórtx.","O caixa vem dos aluguéis de 51% de unidades autônomas do Eldorado Business Tower, Centro Empresarial Rebouças, Av. das Nações Unidas 8.501, São Paulo (matrículas 118.281 a 118.313, 10º RI de São Paulo).","Alienação fiduciária do imóvel, cessão fiduciária de novos direitos creditórios, Fundo de Reserva ou carta fiança, e ESA. Atenção: as garantias são compartilhadas com os CRI Eldorado Anterior (193ª e 204ª séries da 1ª emissão da mesma emissora) e há ainda os CRI Eldorado Subordinada (194ª e 205ª séries).","Adimplente, com 11 obrigações vencidas em aberto entre 31/03/2025 e 28/08/2026: 5 de relatórios periódicos, 2 de demonstrações financeiras, 2 não pecuniárias, 1 de destinação de recursos e 1 de razão de garantia.","Fonte primária: Termo de Securitização da 279ª emissão e resumo da operação no agente fiduciário Vórtx. A fonte anterior, uma página genérica de ofertas da Guide, foi substituída.","https://www.vortx.com.br/investidor/dcm/operacao?id=93143");dossiers.save(d);});
  dossiers.findBySlug("hgbs-bauru").ifPresent(d->{d.refresh("Hedge Brasil Shopping Fundo de Investimento Imobiliário de Responsabilidade Limitada (HGBS11), como devedora; Companhia Província de Securitização como emissora","08.431.747/0001-06 (devedora) — emissora Companhia Província de Securitização, CNPJ 04.200.649/0001-07","Fundo administrado pela Hedge Investments DTVM (CNPJ 07.253.654/0001-76), que também é coordenadora líder da oferta. Cedente: Pátria Malls FII, CNPJ 26.499.833/0001-32, administrado pelo Banco Genial.","Shoppings","Fundo de investimento imobiliário listado — não é SPE","CRI da 138ª emissão, 2ª série, R$ 65.086.000 (a emissão total, em duas séries, soma R$ 91.455.000), emitido em 23/12/2025 com vencimento em 20/12/2028, CDI + 1,60% a.a. ISIN BRPVSCCRI8G8. Agente fiduciário: Oliveira Trust. Sem agência de rating.","O lastro é o preço de aquisição devido pela HGBS11 no Contrato de Venda e Compra pela fração ideal do Shopping Bauru; classificação Anbima corporativo e concentrado.","Alienação fiduciária de 35% do Shopping Bauru, de titularidade da Vértico Bauru; alienação fiduciária de 282.051 cotas do HPDP11 (CNPJ 35.586.415/0001-73) e 1.969.834 cotas do FLRP11 (CNPJ 10.375.382/0001-91), ambas de titularidade da devedora, com cessão fiduciária dos rendimentos; cessão fiduciária de direitos creditórios; e fundos. Atenção: parte relevante da garantia são cotas de outros FIIs do mesmo gestor, o que correlaciona garantia e devedora.","Nenhum evento de inadimplemento registrado nesta base. A emissão é recente, de dezembro de 2025.","Fonte primária: Termo de Securitização da 138ª emissão, obtido na página pública de detalhe da emissão da Província Securitizadora.","https://provinciasecuritizadora.com.br/Detalheemissao?id=264");dossiers.save(d);});
  dossiers.findBySlug("brcr-torre-almirante").ifPresent(d->{d.refresh("Fundo de Investimento Imobiliário – FII – Prime Portfólio (devedor); VERT Companhia Securitizadora como emissora","10.427.246/0001-06 (devedor) — emissora VERT Companhia Securitizadora, CNPJ 25.005.683/0001-09","Fundo administrado pelo BTG Pactual Serviços Financeiros DTVM (CNPJ 59.281.253/0001-23). Cedente: TA Fundo de Investimento Imobiliário, CNPJ 21.085.472/0001-64, administrado pelo Banco Genial.","Escritórios","Fundo de investimento imobiliário — não é SPE","CRI da 64ª emissão, 1ª série — e não 2ª série, como constava nesta base. R$ 95.000.000 em 95.000 CRI, emitido em 13/12/2021 com vencimento em 20/12/2033, CDI + 2,60% a.a., amortização e juros mensais. ISIN BRVERTCRI354. A 2ª série da mesma emissão é outra operação: código 21L0730156, R$ 150 mi, IPCA + 7,10%, vencimento em 22/12/2036.","O caixa vem da fração ideal de 60% do edifício Torre Almirante, na Av. Almirante Barroso 81, e do Edifício Garagem, na Av. Graça Aranha 327, ambos no Rio de Janeiro (matrículas 52.221 a 52.256, 7º Ofício de RI do Rio de Janeiro).","Alienação fiduciária de cotas, cessão fiduciária de direitos creditórios, Fundo de Reserva e Fundo de Despesas. No relatório de fevereiro de 2025 os dois fundos estavam enquadrados (reserva de R$ 2.100.154,61 contra mínimo de R$ 2.100.154,60; despesas de R$ 55.858,71 contra mínimo de R$ 50.000,00). A avaliação do imóvel usada na verificação de 15/01/2025 era de R$ 332.575.000,00.","Adimplente em pagamento e sem nenhuma obrigação vencida em aberto, confirmado pelo cadastro do agente fiduciário e pelo Relatório Anual de 2025 da VERT. A saúde da garantia conta outra história: o índice de cobertura seguia negativo em fevereiro de 2025, sob waiver expirado em julho de 2025, e o pagamento vem dependendo de aporte do devedor. Ver o bloco de cobertura.","Fontes primárias: Termo de Securitização da 64ª emissão e quatro aditamentos, resumo da operação no agente fiduciário Vórtx e Relatório Anual do Agente Fiduciário 2025 da VERT. A fonte anterior apontava para o relatório de um CRA da São Martinho, documento sem relação com esta operação.","https://www.vortx.com.br/investidor/dcm/operacao?id=87626");dossiers.save(d);});
  dossiers.findBySlug("hslg-bts-meli").ifPresent(d->{d.refresh("A confirmar no termo de securitização — emissora Riza Securitizadora S.A.","A confirmar no termo de securitização","A confirmar no termo de securitização","Logístico","A confirmar no termo de securitização","CRI da 199ª emissão, 2ª série de três, R$ 55.000.000 em 55.000 CRI — e não R$ 40 mi, como constava nesta base. A emissão total soma R$ 165.000.000. Emitido em 28/08/2024 com vencimento em 28/04/2034, 100% do CDI + 2,25% a.a. na base 252, juros mensais. ISIN BRIMWLCRIJR8. Custodiante e agente fiduciário: Oliveira Trust; liquidante: Itaú Unibanco; escriturador: Itaú Corretora.","O caixa vem dos aluguéis do Contrato de Locação Araucária, cedidos na proporção da fração ideal de 56,18% do Empreendimento Araucária detida pelo fiduciante, e, se necessário para manter o Índice Mínimo de Cobertura, dos aluguéis do Empreendimento Arujá.","Alienação fiduciária do Imóvel Araucária e do Imóvel Arujá; cessão fiduciária dos aluguéis do Contrato de Locação Araucária, sujeita ao Evento de Integração Araucária, e promessa de cessão dos aluguéis do Empreendimento Arujá; Fundo de Reserva; apólices de seguro patrimonial e de lucros cessantes.","Alerta. A Oliveira Trust classifica o status da operação como INADIMPLENTE, com pendências de relatório gerencial, relatório mensal, relatório de obras e índice financeiro. Nenhuma dessas pendências indica falha de pagamento, mas a exigência de relatório de obras sugere empreendimento ainda em execução, e o índice financeiro em aberto impede aferir a cobertura.","Fonte primária: ficha pública da operação na área do investidor da Oliveira Trust, consultada pelo código 24H2231337.","https://www.oliveiratrust.com.br/investidor/ativos?tipo=cri");dossiers.save(d);});
 };}
 @Bean CommandLineRunner classifyDossiers(DebtorDossierRepository dossiers){return args->{
  dossiers.findBySlug("trx-o-parque").ifPresent(d->{d.classify("SEM ATRASO REGISTRADO","SEM INFORMAÇÃO","O termo é de maio de 2026 e ainda não há relatório de garantias nem apuração de índices publicada. O ponto a acompanhar é a alienação fiduciária anterior em favor da Opea sobre os mesmos imóveis, constituída em 17/08/2023.");dossiers.save(d);});
  dossiers.findBySlug("cpof-fl-plaza").ifPresent(d->{d.classify("ADIMPLENTE","SEM PENDÊNCIA","Nenhuma obrigação vencida em aberto no cadastro do agente fiduciário, inclusive nas categorias de razão e formalização de garantia. Mas não há relatório de garantias público, então a cobertura não pôde ser medida — ausência de pendência não é o mesmo que cobertura verificada.");dossiers.save(d);});
  dossiers.findBySlug("jw-marriott").ifPresent(d->{d.classify("ADIMPLENTE","PENDÊNCIAS ABERTAS","12 apurações de razão de garantia e 4 de formalização de garantia em aberto entre 15/09/2025 e 28/08/2026, com notificação mensal do agente fiduciário. O índice de cobertura da cláusula 7.4 deveria ser apurado todo mês desde agosto de 2025 e consta como não entregue, então não há como aferir a cobertura.");dossiers.save(d);});
  dossiers.findBySlug("edificio-o-parque").ifPresent(d->{d.classify("ADIMPLENTE","PENDÊNCIAS ABERTAS","2 apurações de razão de garantia em aberto. As outras 10 pendências da operação são deveres de informação da emissora, não do devedor.");dossiers.save(d);});
  dossiers.findBySlug("ed-eldorado").ifPresent(d->{d.classify("ADIMPLENTE","PENDÊNCIAS ABERTAS","1 apuração de razão de garantia em aberto. O ponto estrutural é outro: as garantias são compartilhadas com os CRI Eldorado Anterior, então a cobertura não é exclusiva desta série.");dossiers.save(d);});
  dossiers.findBySlug("hgbs-bauru").ifPresent(d->{d.classify("SEM ATRASO REGISTRADO","CALCULADA AQUI","O agente fiduciário não publica cobertura, mas parte da garantia são cotas de FIIs listados, então dá para medir por fora. Em 04/09/2026 a garantia em cotas valia R$ 64,2 mi a preço de tela contra R$ 96,5 mi de saldo devedor das duas séries: 66,5% de cobertura parcial, sem contar os 35% do Shopping Bauru, que não têm avaliação pública. O número é uma marcação, não um valor de saída — ver o bloco de cobertura.");dossiers.save(d);});
  dossiers.findBySlug("brcr-torre-almirante").ifPresent(d->{d.classify("ADIMPLENTE","SOB WAIVER","Duas garantias, dois destinos. O LTV se resolveu: era de 88,74% em 15/01/2024 e caiu para 52,00% em 15/01/2025, com o saldo devedor total em R$ 172,9 mi contra avaliação de R$ 332,6 mi — dentro do teto de 75%. O índice de cobertura não: era -2,11 em agosto de 2024 e seguia em -1,74 em fevereiro de 2025, com NOI de caixa negativo em R$ 3,7 mi, contra o mínimo de 1,3. É evento de vencimento antecipado não automático, dispensado por AGT de 18/12/2023 — e esse waiver valia até julho de 2025, quando o índice deveria voltar a ser cumprido. Em 12/02/2025 o fluxo de recursos foi de novo classificado como insuficiente e o pagamento só ocorreu com aporte do FII Prime Portfólio, mesmo padrão de agosto de 2024. Não há apuração pública posterior ao fim do waiver.");dossiers.save(d);});
  dossiers.findBySlug("hslg-bts-meli").ifPresent(d->{d.classify("SEM ATRASO REGISTRADO","PENDÊNCIAS ABERTAS","A Oliveira Trust marca o status como INADIMPLENTE por pendências de relatório gerencial, relatório mensal, relatório de obras e índice financeiro. Nenhuma delas é falha de pagamento, mas com o índice financeiro em aberto a cobertura não pode ser aferida.");dossiers.save(d);});
 };}
 @Bean CommandLineRunner transparencyScores(TransparencyScoreRepository scores){return args->{
  scores.deleteAll();
  scores.save(new TransparencyScore("trx-o-parque","TRX — O Parque","26E4046156",new BigDecimal("176.6"),2,2,2,0,0,0,"Termo completo e devedora nomeada, mas o portal da Bari só publica termo, aditamentos, atas e anúncios. Não há relatório periódico, apuração de LTV ou índice de cobertura, nem demonstração financeira do Hospital Sírio-Libanês vinculada à operação. A alienação fiduciária anterior em favor da Opea sobre os mesmos imóveis não tem saldo divulgado, então a garantia líquida é desconhecida.",null,null));
  scores.save(new TransparencyScore("cpof-fl-plaza","CPOF — Ed. FL Plaza","25B3552756",new BigDecimal("173.2"),0,0,1,0,0,0,"A operação mais opaca da amostra junto com a BTS Meli, e a segunda maior em valor. A Vórtx não publica documento nenhum: só o resumo cadastral, que lista dois tipos de garantia sem descrevê-los. Não se sabe quem é a devedora, qual imóvel garante o papel nem qual a cobertura. O único dado favorável — zero pendências — é ausência de alerta, não verificação.",null,null));
  scores.save(new TransparencyScore("jw-marriott","JW Marriott Hotel","25H3372118",new BigDecimal("155.7"),0,0,1,0,0,2,"Um ano de notificações do agente fiduciário, mas nenhum documento constitutivo. A devedora não é nomeada em lugar algum. O índice de cobertura da cláusula 7.4 deveria ser apurado todo mês desde agosto de 2025 e consta como não entregue: sabe-se que a medida existe e que ela está faltando, o que é pior do que não haver medida. O acompanhamento é um único informe, referente a 12/2025.",null,LocalDate.of(2025,12,31)));
  scores.save(new TransparencyScore("edificio-o-parque","Edifício O Parque","23H1250138",new BigDecimal("142.9"),2,2,2,0,0,2,"Termo, contrato de cessão e devedor identificados. Falta o que mede a garantia: não há laudo de avaliação nem apuração de razão de garantia publicada, e as duas apurações em aberto no cadastro não têm valor divulgado. O acompanhamento, apesar do nome, é anual: a área aberta tem um informe por ano, referente a dezembro, o mais recente de 12/2025. Sem demonstrações do OPQ FII.",null,LocalDate.of(2025,12,31)));
  scores.save(new TransparencyScore("ed-eldorado","Ed. Eldorado","24E1127893",new BigDecimal("135.0"),1,2,2,0,0,2,"O termo é público mas está cortado: falta o Anexo IX, que relaciona os locatários — ou seja, exatamente quem deve o dinheiro. Sabe-se a natureza do devedor, não o nome. Como as garantias são compartilhadas com os CRI Eldorado Anterior, medir a cobertura desta série exigiria o saldo das outras, que não é divulgado. E o acompanhamento se resume a dois informes anuais, de 12/2024 e 12/2025.",null,LocalDate.of(2025,12,31)));
  scores.save(new TransparencyScore("hgbs-bauru","HGBS — Bauru Shopping","25L3678075",new BigDecimal("68.1"),2,2,2,0,0,2,"Termo integral e devedora listada em bolsa, o melhor ponto de partida da amostra, e a cobertura foi calculada aqui a partir das cotas dadas em garantia. O que a área aberta não dá: apuração de cobertura pelo agente fiduciário, avaliação do Shopping Bauru e relatório mensal da 2ª série — os dois relatórios publicados, de 01/2026 e 02/2026, são da 1ª série.",null,LocalDate.of(2026,2,28)));
  scores.save(new TransparencyScore("brcr-torre-almirante","BRCR — Torre Almirante","21L0729901",new BigDecimal("66.3"),2,2,2,2,0,2,"A operação mais transparente da amostra e a única com cobertura aferível: laudo de avaliação, LTV e índice de cobertura publicados. O que falta é atualidade. A última apuração é de fevereiro de 2025, o waiver do índice expirou em julho de 2025 e nada foi divulgado desde então, então o eixo de cobertura cai de público para parcial. O acompanhamento mensal também parou: os relatórios corriam mês a mês até fevereiro de 2025 e depois só há o informe anual de dezembro. Sem demonstrações do FII Prime Portfólio.",LocalDate.of(2025,2,28),LocalDate.of(2025,12,31)));
  scores.save(new TransparencyScore("hslg-bts-meli","HSLG — BTS Meli","24H2231337",new BigDecimal("63.4"),0,0,1,0,0,0,"A ficha da Oliveira Trust descreve as garantias com detalhe incomum, mas é documento de segunda mão: o termo não está em área aberta e a devedora não é nomeada. O agente marca a operação como inadimplente justamente por não receber relatório gerencial, relatório mensal, relatório de obras e índice financeiro — a opacidade aqui não é do portal, é do próprio devedor.",null,null));
 };}
 @Bean CommandLineRunner coverageMeasurements(CoverageMeasurementRepository coverage){return args->{
  coverage.findBySlug("hgbs-bauru").ifPresent(coverage::delete);
  coverage.save(new CoverageMeasurement("hgbs-bauru",LocalDate.of(2026,9,4),"Parcial — só a alienação fiduciária de cotas, contra o saldo das duas séries da 138ª emissão",new BigDecimal("64197469.21"),new BigDecimal("96521105.26"),new BigDecimal("66.5"),"Cobertura calculada pelo Credit Radar, não publicada pelo agente fiduciário. Saldo devedor da 138ª emissão em 04/09/2026: 26.369 CRI da 1ª série a PU de R$ 1.055,79 (R$ 27.840.126,51) mais 65.086 CRI da 2ª série a PU de R$ 1.055,23 (R$ 68.680.973,14), total de R$ 96.521.105,26 — as duas séries são bullet e dividem as mesmas garantias. Garantia em cotas a preço de fechamento do mesmo dia: 282.051 cotas de HPDP11 a R$ 88,00 (R$ 24.820.488,00) mais 1.969.834 cotas de FLRP11 a R$ 19,99 (R$ 39.376.981,21), total de R$ 64.197.469,21.","Preço de tela não é preço de saída, e aqui a diferença é grande. As 1.969.834 cotas de FLRP11 empenhadas equivalem a 6,1 vezes todo o volume negociado no papel em doze meses (323.151 cotas em 251 pregões, mediana de 547 cotas por dia). A parcela de HPDP11 é menos crítica: 282.051 cotas contra 6.772.895 negociadas em doze meses, ou 4,2% do volume anual — mas a negociação é muito irregular, com mediana de 13 cotas por dia e média de 26.984, o que indica poucos blocos grandes e um mercado quase parado no resto do tempo. Os 61% da garantia que estão em FLRP11 têm marcação, não liquidez. A cobertura também é parcial: não inclui a alienação fiduciária de 35% do Shopping Bauru, que não tem avaliação pública, nem os fundos de reserva e despesas.","Saldo devedor: ficha pública das duas séries na Oliveira Trust, agente fiduciário da emissão. Quantidades de cotas empenhadas: Termo de Securitização da 138ª emissão. Cotações e volumes: série histórica de HPDP11 e FLRP11 na B3."));
 };}
 private void dossier(DebtorDossierRepository r,String... v){r.save(new DebtorDossier(v[0],v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8],v[9],v[10],v[11],v[12]));}
 private void cri(CriDocumentRepository documents,String code,String operation,String issuer,String sourceType,String availability,String finding,String source){documents.save(new CriDocument(code,operation,issuer,sourceType,availability,finding,source));}
 private void add(DebtorResearchRepository research,String debtor,String status,String assessment,String source){research.save(new DebtorResearch(debtor,status,assessment,source));}
